const categoryAliases = { OBC: ['OBC', 'EBC', 'DNT'], Minority: ['Minority'], SC: ['SC'], ST: ['ST'], General: ['General'] }
const incomeRanks = { 'Below ₹1L': 100000, '₹1L–₹2.5L': 250000, '₹2.5L–₹5L': 500000, 'Above ₹5L': 800000 }
const educationPatterns = { School: /class|school|ix|x|xi|xii|9-10|9-12|1-10|11-12/i, Undergraduate: /\bug\b|undergraduate|degree|diploma/i, Postgraduate: /\bpg\b|postgraduate|ph\.?d|fellowship|research|master/i }

export function matchesEducation(scheme, education) {
  return educationPatterns[education]?.test(scheme.educationLevel) ?? true
}

export function matchesCategory(scheme, category) {
  const accepted = categoryAliases[category] ?? [category]
  return scheme.categories.some((schemeCategory) => accepted.includes(schemeCategory))
}

export function matchesIncome(scheme, income) {
  if (scheme.incomeLimit === null || scheme.incomeLimit === 'unknown') return true
  const requestedLimit = incomeRanks[income]
  return requestedLimit ? scheme.incomeLimit >= requestedLimit : true
}

export function matchSchemes(answers) {
  if (!answers) return []
  const scored = schemes
    .filter((scheme) => scheme.active)
    .map((scheme) => {
      const categoryMatch = matchesCategory(scheme, answers.category)
      const educationMatch = matchesEducation(scheme, answers.education)
      const incomeMatch = matchesIncome(scheme, answers.income)
      const score = (categoryMatch ? 4 : 0) + (educationMatch ? 3 : 0) + (incomeMatch ? 2 : 0)
      return { scheme, categoryMatch, educationMatch, incomeMatch, score }
    })
    .filter((result) => result.categoryMatch && result.educationMatch && result.incomeMatch)
    .sort((a, b) => b.score - a.score || a.scheme.serial - b.scheme.serial)
    .map(({ scheme, score }) => ({
      ...scheme,
      score,
      reason: buildMatchReason(scheme, answers),
    }))
  return scored
}

const localizedReasonTemplates = {
  English: ({ category, education, income }) => `Matches your ${category} category, ${education} study, and ${income} income bracket.`,
  Hindi: ({ category, education, income }) => `यह आपकी ${category} श्रेणी, ${education} की पढ़ाई और ${income} आय सीमा से मेल खाता है।`,
  Tamil: ({ category, education, income }) => `இது உங்கள் ${category} பிரிவு, ${education} படிப்பு மற்றும் ${income} வருமான வரம்புடன் பொருந்துகிறது.`,
  Bengali: ({ category, education, income }) => `এটি আপনার ${category} শ্রেণি, ${education} পড়াশোনা এবং ${income} আয়ের সীমার সঙ্গে মেলে।`,
  Malayalam: ({ category, education, income }) => `ഇത് നിങ്ങളുടെ ${category} വിഭാഗം, ${education} പഠനം, ${income} വരുമാന പരിധി എന്നിവയുമായി പൊരുത്തപ്പെടുന്നു.`,
  Punjabi: ({ category, education, income }) => `ਇਹ ਤੁਹਾਡੀ ${category} ਸ਼੍ਰੇਣੀ, ${education} ਦੀ ਪੜ੍ਹਾਈ ਅਤੇ ${income} ਆਮਦਨ ਸੀਮਾ ਨਾਲ ਮੇਲ ਖਾਂਦਾ ਹੈ।`,
  Marathi: ({ category, education, income }) => `हे तुमची ${category} श्रेणी, ${education} शिक्षण आणि ${income} उत्पन्न मर्यादेशी जुळते.`,
  Kannada: ({ category, education, income }) => `ಇದು ನಿಮ್ಮ ${category} ವರ್ಗ, ${education} ಅಧ್ಯಯನ ಮತ್ತು ${income} ಆದಾಯ ಮಿತಿಗೆ ಹೊಂದಿಕೆಯಾಗುತ್ತದೆ.`,
}

export function buildMatchReason(scheme, answers) {
  const selectedLanguage = getLanguage(answers?.language).name
  const details = {
    category: getOptionLabel('category', answers?.category || 'General', selectedLanguage),
    education: getOptionLabel('education', answers?.education || 'Undergraduate', selectedLanguage),
    income: getOptionLabel('income', answers?.income || 'Below ₹1L', selectedLanguage),
  }
  const template = localizedReasonTemplates[selectedLanguage] || localizedReasonTemplates.English
  return template(details)
}
